def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != bg]

    bars = None
    for c in colors:
        top = [j for j, x in enumerate(grid[0]) if x == c]
        bottom = [j for j, x in enumerate(grid[-1]) if x == c]
        left = [i for i in range(h) if grid[i][0] == c]
        right = [i for i in range(h) if grid[i][-1] == c]
        if top and bottom and len(top) == len(bottom):
            bars = ("h", min(top), min(bottom), len(top))
            break
        if left and right and len(left) == len(right):
            bars = ("v", min(left), min(right), len(left))
            break

    if bars is None:
        return [row[:] for row in grid]

    axis, s1, s2, length = bars
    marker_color = max((c for c in colors if c != next(
        c for c in colors
        if (axis == "h" and all(grid[0][j] == c for j in range(s1, s1 + length)))
        or (axis == "v" and all(grid[i][0] == c for i in range(s1, s1 + length)))
    )), key=lambda c: counts[c], default=None)
    # The non-background color other than the border-bar color marks the rays.
    rail = grid[0][s1] if axis == "h" else grid[s1][0]
    marker_color = max((c for c in colors if c != rail), key=lambda c: counts[c])

    out = [row[:] for row in grid]
    markers = [(i, j) for i in range(h) for j in range(w)
               if grid[i][j] == marker_color]

    for i, j in markers:
        if axis == "h":
            if s1 <= j < s1 + length:
                mate = s2 + (j - s1)
            elif s2 <= j < s2 + length:
                mate = s1 + (j - s2)
            else:
                continue
            for r in range(1, h - 1):
                out[r][j] = marker_color
                out[r][mate] = marker_color
        else:
            if s1 <= i < s1 + length:
                mate = s2 + (i - s1)
            elif s2 <= i < s2 + length:
                mate = s1 + (i - s2)
            else:
                continue
            for c in range(1, w - 1):
                out[i][c] = marker_color
                out[mate][c] = marker_color

    for i, j in markers:
        out[i][j] = 4
    return out
